def find_ch_id(sec_str):
    if sec_str.startswith("265") and len(sec_str) > 3:
        return "crpc-ch-22a"
    if sec_str in ("516A",):
        return "crpc-ch-43"
    if sec_str in ("4A",):
        return "crpc-ch-1"
    if sec_str in ("17A",):
        return "crpc-ch-2"
    if sec_str in ("29A", "29B", "29C", "34A", "35A"):
        return "crpc-ch-3"
    if sec_str in ("46A", "46B", "46C", "46D", "54A"):
        return "crpc-ch-5"
    if sec_str in ("70A", "86A", "90A", "93A", "93B", "93C"):
        return "crpc-ch-6"
    if sec_str.startswith("99") and len(sec_str) > 2:
        return "crpc-ch-7"
    if sec_str in ("126A",):
        return "crpc-ch-8"
    if sec_str in ("132A",):
        return "crpc-ch-9"
    if sec_str in ("139A",):
        return "crpc-ch-10"
    if sec_str in ("164A", "167A", "174A"):
        return "crpc-ch-14"
    if sec_str in ("196A", "196B", "198A", "199A", "199B"):
        return "crpc-ch-15"
    if sec_str in ("205A", "205B", "205C", "205D", "205E"):
        return "crpc-ch-17"
    if sec_str in ("222A",):
        return "crpc-ch-19"
    if sec_str in ("241A", "250A"):
        return "crpc-ch-20"
    if sec_str in ("339A", "339B", "339C", "339D", "344A", "350A"):
        return "crpc-ch-24"
    if sec_str in ("402A",):
        return "crpc-ch-29"
    if sec_str in ("406A", "411A", "415A", "417A", "426A"):
        return "crpc-ch-31"
    if sec_str in ("439A", "442A"):
        return "crpc-ch-32"
    if sec_str in ("476A", "476B"):
        return "crpc-ch-35"
    if sec_str in ("491A",):
        return "crpc-ch-37"
    if sec_str in ("508A",):
        return "crpc-ch-40"
    if sec_str in ("510A",):
        return "crpc-ch-41"
    if sec_str in ("514A", "514B"):
        return "crpc-ch-42"
    if sec_str in ("526A", "526B", "528A", "528B", "528C", "528D", "528E", "528F"):
        return "crpc-ch-44"
    if sec_str in ("539A", "539B", "540A", "546A", "561A"):
        return "crpc-ch-46"

    m = re.match(r'^([0-9]+)', sec_str)
    if m:
        val = int(m.group(1))
        for ch in CHAPTERS_DEF:
            if ch[4] <= val <= ch[5]:
                return ch[0]
    return "crpc-ch-46"

