        clean_content = sec['contentBengali'].replace("`", "\\`").replace("${", "\\${")
        ts_lines.append(f"          titleBengali: '{clean_title_bn}',")
        ts_lines.append(f"          titleEnglish: '{clean_title_en}',")
        ts_lines.append(f"          contentBengali: `{clean_content}`,")
